import 'package:flutter/material.dart'; import '../../repositories/course_repository.dart'; import '../../repositories/exam_repository.dart'; import '../../widgets/exam_card.dart'; import 'take_exam_page.dart'; class ExamsPage extends StatelessWidget { const ExamsPage({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('الاختبارات')),body:StreamBuilder(stream:CourseRepository().watch(),builder:(c,cs){if(!cs.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:cs.data!.map((course)=>StreamBuilder(stream:ExamRepository().watch(course.id),builder:(c,es){if(!es.hasData)return const SizedBox();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.all(12),child:Text(course.name,style:Theme.of(c).textTheme.titleLarge)),...es.data!.map((exam)=>ExamCard(exam:exam,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>TakeExamPage(exam:exam))))]);})).toList());})); }